def first_even(lst: list) -> int | None:
    for num in lst:
        if isinstance(num, int) and num % 2 == 0:
            return num
    return None

def re_arrange_array(arr, n):
    # Partition array so that all negative numbers come before positive numbers
    i = 0
    for j in range(n):
        if arr[j] < 0:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
    return arr

from typing import Iterable

def find_remainder(collection: Iterable[int], n: int) -> int:
    result = 1
    for num in collection:
        result = (result * num) % n
    return result

def max_sub_array_sum(arr: list, n: int) -> int:
    max_sum = current_sum = arr[0]
    for i in range(1, n):
        current_sum = max(arr[i], current_sum + arr[i])
        max_sum = max(max_sum, current_sum)
    return max_sum

from collections.abc import Collection

def div_of_nums(values: Collection[int], m: int, n: int) -> list:
    return [v for v in values if v % m == 0 and v % n == 0]

def highest_Power_of_2(value: int) -> int:
    if value < 1:
        return 0
    power = 1
    while power <= value:
        power <<= 1
    return power >> 1

def flatten_list(collection):
    result = []
    for item in collection:
        if isinstance(item, (list, tuple)):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result

def len_log(words: list[str]) -> int:
    if not words:
        return 0
    return max(len(word) for word in words)

