from typing import Collection, Tuple

def check_k_elements(collection: Collection[Tuple], k: int) -> bool:
    unique_items = set()
    for tup in collection:
        unique_items.update(tup)
        if len(unique_items) >= k:
            return True
    return False

def min_flip_to_make_string_alternate(s: str) -> int:
    # The two possible alternating patterns for a binary string:
    # pattern1: "010101..."
    # pattern2: "101010..."
    flips_pattern1 = 0
    flips_pattern2 = 0

    for i, ch in enumerate(s):
        expected_char_1 = '0' if i % 2 == 0 else '1'
        expected_char_2 = '1' if i % 2 == 0 else '0'

        if ch != expected_char_1:
            flips_pattern1 += 1
        if ch != expected_char_2:
            flips_pattern2 += 1

    return min(flips_pattern1, flips_pattern2)

def next_power_of_2(n: int) -> int:
    if n <= 1:
        return 1
    # Start from 1 and shift left until >= n
    power = 1
    while power < n:
        power <<= 1
    return power

def length_Of_Last_Word(s: str) -> int:
    s = s.rstrip()
