def move_num(text: str) -> str:
    letters = []
    digits = []
    for ch in text:
        if ch.isdigit():
            digits.append(ch)
        else:
            letters.append(ch)
    return ''.join(letters) + ''.join(digits)

def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome after 9...9 is 10...01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left = s[:half_len]

    # Form palindrome from left side
    palindrome = make_palindrome(left, length % 2 != 0)
    if palindrome >= int(s):
        return palindrome

    # Increment left part and form palindrome again
    left_int = int(left) + 1
    left = str(left_int)
    # If increment causes length increase, handle separately
    if len(left) > half_len:
        # e.g. 999 + 1 = 1000, palindrome will be 100...001 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    return make_palindrome(left, length % 2 != 0)

def is_decimal(value: str) -> bool:
    try:
        float_val = float(value)
    except ValueError:
        return False

    if '.' not in value:
        # No decimal point, precision 0 -> fail
        return False

    # Split on decimal point
    parts = value.split('.', 1)
    if len(parts) != 2:
        return False

    decimal_part = parts[1]
    # Allow trailing zeros, but must have exactly 2 digits after decimal
    return len(decimal_part) == 2 and decimal_part.isdigit()

