def sum_Of_product(n: int) -> int:
    # sum_{k=0}^n C(n,k)*C(n,k) = C(2n,n)
    return comb(2*n, n)

def odd_length_sum(arr):
    total = 0
    n = len(arr)
    for start in range(n):
        for end in range(start, n):
            length = end - start + 1
            if length % 2 == 1:
                total += sum(arr[start:end+1])
    return total

from math import comb

def even_binomial_Coeff_Sum(n: int) -> int:
    return sum(comb(n, k) for k in range(0, n+1, 2))

def zip_tuples(t1: tuple, t2: tuple) -> tuple:
    length = max(len(t1), len(t2))
    result = []
    for i in range(length):
        if i < len(t1) and i < len(t2):
            result.append((t1[i], t2[i]))
    return tuple(result)

