import math

def min_Jumps(d: float, length: float) -> float:
    if d == 0:
        return 0.0
    if length == 0:
        return float('inf')  # cannot move if step length is zero
    # If a single jump length is greater or equal to d, one jump is enough.
    if length >= d:
        return 1.0
    # Otherwise, calculate the minimal number of jumps needed.
    jumps = math.ceil(d / length)
    return float(jumps)
